INSERT INTO `academic_reviews` VALUES (1,2,7,5,'Dr. Ahmed is an exceptional professor. His AI lectures are clear, well-structured, and always include real-world examples. He genuinely cares about students\' understanding. Best professor I\'ve had!',0,'2026-06-24 03:30:44'),(2,2,8,4,'Great teaching style and very knowledgeable. Office hours are very helpful. Sometimes the pace is a bit fast but overall excellent course.',0,'2026-06-24 03:30:44'),(3,2,9,5,'Truly inspiring! Changed my perspective on AI completely. The research opportunities he offers to students are incredible.',1,'2026-06-24 03:30:44'),(4,2,12,4,'Very approachable and helpful. The course projects are challenging but you learn a lot from them.',0,'2026-06-24 03:30:44'),(5,3,7,5,'Dr. Sara\'s software engineering course is the most practical course I\'ve taken. Real industry practices, not just theory. She brings in guest speakers from top companies too!',0,'2026-06-24 03:30:44'),(6,3,8,5,'Amazing professor! She really understands what the industry needs and teaches accordingly. Her code reviews are incredibly detailed and helpful.',0,'2026-06-24 03:30:44'),(7,3,12,4,'Good teacher with high standards. The workload is heavy but you come out very well prepared.',1,'2026-06-24 03:30:44'),(8,4,9,4,'Dr. Omar\'s database course completely changed how I think about data. The query optimization techniques I learned saved my current project from being unusably slow.',0,'2026-06-24 03:30:44'),(9,4,7,3,'Knowledgeable professor but the exam questions could be clearer. Office hours are very helpful when you go.',1,'2026-06-24 03:30:44'),(10,4,13,5,'Best database professor I\'ve ever had. The hands-on SQL workshops are gold. I got my internship largely thanks to the SQL skills from his course.',0,'2026-06-24 03:30:44'),(11,5,14,5,'Dr. Layla is pioneering medical informatics research at our university. Her passion for the intersection of medicine and technology is contagious. Highly recommend!',0,'2026-06-24 03:30:44'),(12,5,10,4,'Brilliant doctor and researcher. The course gives a great overview of how AI is transforming healthcare.',0,'2026-06-24 03:30:44'),(13,6,11,5,'Dr. Youssef\'s electrical engineering lectures are always perfectly organized. He never leaves a question unanswered and his lab sessions are fantastic.',0,'2026-06-24 03:30:44'),(14,6,13,4,'Great professor, very patient with students. The exams are fair and reflect what was taught in lectures.',1,'2026-06-24 03:30:44'),(15,37,51,5,'دكتوري المفضل',0,'2026-06-25 06:53:41');
