INSERT INTO `group_posts` VALUES (1,1,7,'Sharing my complete Data Structures notes — trees, graphs, heaps, and sorting algorithms. 120 pages of organized notes. Download in Files section!',NULL,'2026-06-24 03:30:43','2026-06-24 03:30:43'),(2,1,8,'The Operating Systems exam is next Tuesday. Anyone want to do a last-minute review session on Friday afternoon?',NULL,'2026-06-24 03:30:43','2026-06-24 03:30:43'),(3,2,2,'New research paper published! \'Adaptive Learning Systems using Reinforcement Learning\' — link in my profile. Co-authored with kareem_m.',NULL,'2026-06-24 03:30:43','2026-06-24 03:30:43'),(4,2,9,'Working on implementing a Transformer model from scratch. Getting ~91% accuracy on the CIFAR-10 dataset. Happy to share the code!',NULL,'2026-06-24 03:30:43','2026-06-24 03:30:43'),(5,3,8,'Just deployed my first full-stack app to production! React + Node.js + MySQL. Learned so much from this group. Thanks everyone 🙏',NULL,'2026-06-24 03:30:43','2026-06-24 03:30:43'),(6,6,17,'Applications are now open for the Spring 2025 Startup Grant — up to $10,000 no-equity funding. Deadline: March 31. Apply at the link in my profile!',NULL,'2026-06-24 03:30:43','2026-06-24 03:30:43'),(7,7,15,'We placed 2nd in the national CTF! Great performance from everyone. Next competition is in 6 weeks — let\'s step up our reverse engineering skills.',NULL,'2026-06-24 03:30:43','2026-06-24 03:30:43');
/*!40000 ALTER TABLE `group_posts` ENABLE KEYS */;
UNLOCK TABLES;

