INSERT INTO `groups` VALUES (1,7,'CS Study Group','Computer Science students sharing resources, notes, and study tips for all CS courses.',NULL,0,'2026-06-24 03:30:43'),(2,2,'AI Research Lab','Research group focused on AI, machine learning, and deep learning projects and publications.',NULL,0,'2026-06-24 03:30:43'),(3,8,'Web Dev Community','Frontend and backend developers building real-world projects and learning together.',NULL,0,'2026-06-24 03:30:43'),(4,11,'IoT & Embedded Systems','Engineers working with microcontrollers, sensors, and smart devices. Weekly project showcases.',NULL,0,'2026-06-24 03:30:43'),(5,10,'Psychology & Wellbeing Club','Supporting student mental health, sharing research, and organizing wellbeing workshops.',NULL,0,'2026-06-24 03:30:43'),(6,17,'Startup Founders Network','Connect student entrepreneurs with mentors and investors. Pitch sessions every month.',NULL,0,'2026-06-24 03:30:43'),(7,15,'Cybersecurity CTF Team','Competitive hacking team preparing for CTF competitions. All skill levels welcome!',NULL,0,'2026-06-24 03:30:43'),(8,16,'Business & Entrepreneurship','For business students and aspiring entrepreneurs. Case studies, competitions, networking.',NULL,0,'2026-06-24 03:30:43');
