INSERT INTO `projects` VALUES (1,7,'AI Study Planner','An intelligent study scheduler that uses ML to optimize your revision timetable based on exam dates, difficulty, and past performance. Built with React and Python/Flask backend.','IT','mvp',5000.00,'https://github.com/sample/ai-study-planner',NULL,'2026-06-24 03:30:43'),(2,9,'Smart Plagiarism Detector','Deep learning model for detecting academic plagiarism with 95% accuracy. Uses BERT embeddings and cosine similarity. Deployed as a web service for university use.','IT','launched',0.00,'https://github.com/sample/plagiarism-detector',NULL,'2026-06-24 03:30:43'),(3,11,'Campus Navigation System','Indoor navigation system using BLE beacons and ESP32 microcontrollers. Helps students find classrooms, labs, and facilities across 12 campus buildings.','Engineering','prototype',8000.00,NULL,NULL,'2026-06-24 03:30:43'),(4,8,'Student Mental Health App','Mobile application connecting students with mental health resources, anonymous peer support, and professional counseling booking. React Native + Node.js.','IT','idea',15000.00,NULL,NULL,'2026-06-24 03:30:43'),(5,16,'UniTutor — Peer Learning Platform','Subscription platform connecting students for paid peer tutoring sessions. Built marketplace with verified tutors, scheduling, and payment integration.','Business','mvp',20000.00,NULL,'https://unitutor-demo.vercel.app','2026-06-24 03:30:43'),(6,15,'Campus IoT Security Monitor','Network security monitoring system specifically designed for university campus IoT devices. Detects anomalies, unauthorized access, and vulnerability scanning.','IT','prototype',12000.00,NULL,NULL,'2026-06-24 03:30:43'),(7,14,'AI Medical Diagnosis Assistant','Machine learning model that assists medical students in differential diagnosis. Trained on 50,000+ clinical cases. Accuracy: 87% on test set.','Medicine','prototype',30000.00,'https://github.com/sample/med-ai',NULL,'2026-06-24 03:30:43'),(8,13,'Smart Building Energy Manager','IoT-based building energy management system that reduces electricity consumption by 35% through smart scheduling of HVAC, lighting, and appliances.','Engineering','launched',0.00,NULL,NULL,'2026-06-24 03:30:43');
/*!40000 ALTER TABLE `projects` ENABLE KEYS */;
